<?php declare(strict_types=1);require __DIR__.'/../../includes/bootstrap.php';require_student();verify_csrf($_POST['csrf_token']??null);$uid=(int)current_user()['user_id'];$cat=(int)$_POST['category_id'];$limit=(float)$_POST['limit_amount'];$th=(float)$_POST['alert_threshold_percent'];if(!find_category($cat,$uid,'expense')||$limit<0||$th<0||$th>100){flash('error','Invalid budget values.');redirect('student/budgets.php');}db()->prepare('INSERT INTO budgets(user_id,category_id,month_start,limit_amount,alert_threshold_percent,is_active) VALUES(?,?,?,?,?,TRUE) ON DUPLICATE KEY UPDATE limit_amount=VALUES(limit_amount),alert_threshold_percent=VALUES(alert_threshold_percent),is_active=TRUE')->execute([$uid,$cat,month_start(),$limit,$th]);flash('success','Budget saved.');redirect('student/budgets.php');